def escape_link_text(text: str) -> str:
    return text.replace("\\", "\\\\").replace("[", "\\[").replace("]", "\\]")


def escape_cell(text: str) -> str:
    return text.replace("|", "\\|")


class _Links:
    """1 つのファイルの reference-style のリンクと、末尾に書く定義の行。"""

    def __init__(self, file: str):
        self.file = file
        self.definitions: dict[str, tuple[str, str]] = {}

    def link(self, text: str, target_id: str, target_file: str, title: str) -> str:
        if target_file == self.file:
            href = f"#{target_id}"
        else:
            relative = posixpath.relpath(target_file, posixpath.dirname(self.file))
            href = f"{relative}#{target_id}"
        self.definitions[target_id] = (href, title)
        return f"[{escape_link_text(text)}][{target_id}]"

    def file_link(self, text: str, target_file: str, title: str) -> str:
        """ID を持たないファイル (ディレクトリ docs/domains/ の直下の生成したファイルなど) へのリンク。ラベルはファイル名。"""
        label = posixpath.basename(target_file)
        self.definitions[label] = (posixpath.relpath(target_file, posixpath.dirname(self.file)), title)
        return f"[{escape_link_text(text)}][{label}]"

    def lines(self) -> list[str]:
        return [f'[{label}]: {href} "{title}"' for label, (href, title) in sorted(self.definitions.items())]


def _file_name(symbol: str) -> str:
    return names.FILE_KINDS.get(symbol) or names.HANDWRITTEN_FILE_KINDS[symbol]


def file_path(domain: Domain, symbol: str) -> str:
    return f"{domain.dir}/{_file_name(symbol)}"


def _file_id(domain: Domain, symbol: str) -> str:
    return names.build_id([names.Part("d", domain.name), names.Part(symbol, None)])


def _file_title(domain: Domain, symbol: str) -> str:
    return names.join_parts([domain.full_name(), names.format_part(symbol, _file_name(symbol))])


def entry_file(entry: Entry) -> str:
    if entry.domain is None:
        return PERMISSIONS_PATH  # ロール
    return file_path(entry.domain, ENTRY_FILES.get(entry.symbol, "models"))


def _entry_link(links: _Links, entry: Entry, text: str) -> str:
    return links.link(text, entry.id, entry_file(entry), entry.full_name())


def _reference_text(entry: Entry, from_domain: Domain) -> str:
    """ほかの定義を指すリンクの表示の文。同じドメインなら、完全な名前からドメインを省いたもの
    (「モデル「貸出」の属性「貸出状態」」)。ほかのドメインの定義とロールなら完全な名前。"""
    if entry.domain is not None and entry.domain is from_domain:
        return names.join_parts([names.format_part(e.symbol, e.name_ja) for e in entry.lineage()])
    return entry.full_name()


def _document(source: str, anchor: str | None, blocks: list[str], links: _Links) -> str:
    parts = [generated_header.markdown_line(source)]
    if anchor:
        parts.append(f'<a name="{anchor}"></a>')
    text = "\n".join(parts) + "\n\n" + "\n\n".join(blocks)
    definition_lines = links.lines()
    if definition_lines:
        text += "\n\n" + "\n".join(definition_lines)
    return text + "\n"


def _definition_block(entry: Entry, extra: str = "") -> str:
    heading = "#" * HEADING_LEVELS[entry.symbol]
    title = f"{names.format_part(entry.symbol, entry.name_ja)} `{entry.name}`"
    body = entry.definition
    if extra:
        body += extra if body.endswith("。") else f" {extra}"
    return f'<a name="{entry.id}"></a>\n\n{heading} {title}\n\n{body}'


def _referencing_models(project: Project) -> dict[str, list[Entry]]:
    """モデルの ID から、そのモデルを参照するモデルへの対応。定義の並び順で、重複は除く。"""
    result: dict[str, list[Entry]] = {}
    for domain in project.domains:
        for model in domain.models:
            for attribute in model.children:
                target = attribute.refers_to
                if target in project.entries and model not in result.setdefault(target, []):
                    result[target].append(model)
    return result


def render_models(project: Project, domain: Domain, referencing: dict[str, list[Entry]]) -> str:
    path = file_path(domain, "models")
    links = _Links(path)
    blocks = [f"# {domain.full_name()} のモデル"]
    for model in domain.models:
        blocks.append(_definition_block(model))
        users = referencing.get(model.id, [])
        if users:
            listed = "・".join(_entry_link(links, m, _reference_text(m, domain)) for m in users)
            blocks.append(f"このモデルを参照するモデル: {listed}")
        for attribute in model.children:
            extra = ""
            if attribute.refers_to in project.entries:
                target = project.entries[attribute.refers_to]
                extra = "参照先: " + _entry_link(links, target, _reference_text(target, domain))
            blocks.append(_definition_block(attribute, extra))
            machine = project.state_machines.get(attribute.id)
            if machine is not None:
                blocks += _state_machine_blocks(project, machine, attribute, links)
            for value in attribute.children:
                blocks.append(_definition_block(value))
    return _document(f"{domain.dir}/", _file_id(domain, "models"), blocks, links)


def _table_row(cells: list[str]) -> str:
    """表の 1 行。空のセルは空白 1 つにする。"""
    return "|" + "|".join(f" {c} " if c else " " for c in cells) + "|"


def _state_machine_blocks(project: Project, machine: StateMachine, attribute: Entry, links: _Links) -> list[str]:
    """属性の状態の遷移の、最初の状態を書いた文・遷移の表・図。"""
    values = {value.name: value for value in attribute.children}

    def link(entry: Entry) -> str:
        return escape_cell(_entry_link(links, entry, entry.name_ja))

    intro = "状態の遷移:"
    if machine.initial is not None:
        initial = values[machine.initial.name]
        text = names.format_part(initial.symbol, initial.name_ja)
        intro = f"状態の遷移 (最初の状態: {_entry_link(links, initial, text)}):"
    rows = [_table_row(STATE_MACHINE_HEADER), "|" + "---|" * len(STATE_MACHINE_HEADER)]
    diagram = ["```mermaid", "stateDiagram-v2"]
    diagram += [f'  state "{value.name_ja}" as {STATE_ID_PREFIX}{value.name}' for value in attribute.children]
    if machine.initial is not None:
        diagram.append(f"  [*] --> {STATE_ID_PREFIX}{machine.initial.name}")
    for transition in machine.transitions:
        operations = [project.entries[t] for t in transition.targets("operations")]
        preconditions = [project.entries[t] for t in transition.targets("preconditions")]
        rows.append(_table_row([
            "・".join(link(values[s.name]) for s in transition.from_values),
            link(values[transition.to.name]),
            "・".join(link(e) for e in operations),
            "・".join(link(e) for e in preconditions),
        ]))
        label = "・".join(e.name_ja for e in operations)
        if preconditions:
            label = (label + " " if label else "") + "[" + "・".join(e.name_ja for e in preconditions) + "]"
        for state in transition.from_values:
            arrow = f"  {STATE_ID_PREFIX}{state.name} --> {STATE_ID_PREFIX}{transition.to.name}"
            diagram.append(f"{arrow} : {label}" if label else arrow)
    diagram.append("```")
    return [intro, "\n".join(rows), "\n".join(diagram)]


def render_unclassified_app_terms(domain: Domain) -> str:
    path = file_path(domain, "unclassified_app_terms")
    links = _Links(path)
    blocks = [f"# {domain.full_name()} の{names.KINDS['ut'].label}"]
    blocks += [_definition_block(term) for term in domain.terms]
    return _document(f"{domain.dir}/", _file_id(domain, "unclassified_app_terms"), blocks, links)


def _function_items(project: Project, domain: Domain, entry: Entry, links: _Links) -> str | None:
    """定義の文の後に出す、参照の箇条書き。参照が無ければ None。roles を省いた操作には「行えるロール: 無し」を出す。"""
    lines = []
    for key, label in FUNCTION_ITEMS.items():
        targets = [project.entries[r.target] for r in entry.references if r.key == key]
        if targets:
            listed = "・".join(_entry_link(links, t, _reference_text(t, domain)) for t in targets)
            lines.append(f"- {label}: {listed}")
        elif key == "roles" and entry.symbol == "op":
            lines.append(NO_ROLES_ITEM)
    return "\n".join(lines) if lines else None


def render_functions(project: Project, domain: Domain) -> str:
    path = file_path(domain, "functions")
    links = _Links(path)
    blocks = [f"# {domain.full_name()} の操作・前提・イベント"]
    for entry in [*domain.operations, *domain.preconditions, *domain.events]:
        blocks.append(_definition_block(entry))
        items = _function_items(project, domain, entry, links)
        if items:
            blocks.append(items)
    return _document(f"{domain.dir}/", _file_id(domain, "functions"), blocks, links)


def _kind_text(entry: Entry) -> str:
    """用語の索引の「種類」の列。ドメインの中の親の「種類 + 名前」と、自分の種類の名前。"""
    parents = [names.format_part(e.symbol, e.name_ja) for e in entry.lineage()[:-1]]
    return names.join_parts([*parents, entry.kind_label])


def _sorted_terms(entries: list[Entry]) -> list[Entry]:
    return sorted(entries, key=lambda e: (e.name_ja, e.id))


def render_terms(domain: Domain) -> str:
    path = file_path(domain, "terms")
    links = _Links(path)
    rows = ["| 用語 | 種類 | 英語名 |", "|---|---|---|"]
    for entry in _sorted_terms(list(domain.entries())):
        term = escape_cell(_entry_link(links, entry, entry.name_ja))
        rows.append(f"| {term} | {escape_cell(_kind_text(entry))} | `{entry.name}` |")
    blocks = [f"# {domain.full_name()} の用語の索引", "\n".join(rows)]
    return _document(f"{domain.dir}/", _file_id(domain, "terms"), blocks, links)


def _project_source(project: Project) -> str:
    """プロジェクトの全体から作るファイルの生成元。ロールがあれば、ドメインの外の YAML も読むので docs/。"""
    return "docs/" if project.roles else f"{DOMAINS_DIR.as_posix()}/"


def render_glossary(project: Project) -> str:
    links = _Links(GLOSSARY_PATH)
    rows = ["| 用語 | 種類 | 英語名 | ドメイン |", "|---|---|---|---|"]
    all_entries = [e for d in project.domains for e in d.entries()] + project.roles
    for entry in _sorted_terms(all_entries):
        domain = entry.domain
        term = escape_cell(_entry_link(links, entry, entry.name_ja))
        domain_cell = " "  # ロールはドメインを持たないので、セルを空にする
        if domain is not None:
            domain_link = links.link(f"`{domain.name}`", domain.id, f"{domain.dir}/{README}", domain.full_name())
            domain_cell = f" {domain_link} "
        rows.append(f"| {term} | {escape_cell(_kind_text(entry))} | `{entry.name}` |{domain_cell}|")
    blocks = ["# 用語の索引", "\n".join(rows)]
    return _document(_project_source(project), None, blocks, links)


def render_permissions(project: Project) -> str:
    """ロールの定義の節と、操作ごとの行えるロールの表。操作が無ければ表を出さない。"""
    links = _Links(PERMISSIONS_PATH)
    blocks = ["# ロールと操作"]
    blocks += [_definition_block(role) for role in project.roles]
    operations = [op for domain in project.domains for op in domain.operations]
    if operations:
        header = ["操作", "ドメイン"]
        header += [_entry_link(links, role, role.name_ja) for role in project.roles]
        rows = ["| " + " | ".join(escape_cell(h) for h in header) + " |", "|" + "---|" * len(header)]
        for op in operations:
            permitted = {r.target for r in op.references if r.key == "roles"}
            domain = op.domain
            cells = [
                escape_cell(_entry_link(links, op, op.name_ja)),
                links.link(f"`{domain.name}`", domain.id, f"{domain.dir}/{README}", domain.full_name()),
            ]
            cells += [PERMITTED if role.id in permitted else "" for role in project.roles]
            rows.append(_table_row(cells))
        blocks += [PERMISSIONS_TABLE_HEADING, "\n".join(rows)]
    return _document("docs/", None, blocks, links)


def _domain_link(links: _Links, domain: Domain, text: str) -> str:
    return links.link(text, domain.id, f"{domain.dir}/{README}", domain.full_name())


def _directory_name(domain: Domain) -> str:
    return posixpath.basename(domain.dir)


def render_dependencies(project: Project, domain: Domain, dependencies: list[DomainDependency]) -> str:
    """ドメインが、ほかのドメインに依存する元になった参照の表。"""
    path = file_path(domain, "dependencies")
    links = _Links(path)
    rows = [_table_row(DEPENDENCIES_HEADER), "|" + "---|" * len(DEPENDENCIES_HEADER)]
    for dependency in dependencies:
        target_domain = _domain_link(links, dependency.target, f"`{dependency.target.name}`")
        for reference in dependency.references:
            source = _entry_link(links, reference.source, _reference_text(reference.source, domain))
            if reference.in_state_machine:
                source += "の状態の遷移"
            target = project.entries[reference.target]
            rows.append(_table_row([
                target_domain,
                escape_cell(source),
                f"`{reference.key}`",
                escape_cell(_entry_link(links, target, _reference_text(target, domain))),
            ]))
    blocks = [f"# {domain.full_name()} の依存", "\n".join(rows)]
    return _document(f"{domain.dir}/", _file_id(domain, "dependencies"), blocks, links)


def render_domains_dependencies(project: Project, dependencies: dict[str, list[DomainDependency]]) -> str:
    """ドメインの依存の表と図。表はドメインの番号の順。図は、依存するドメインから依存先のドメインへの矢印を描く。"""
    links = _Links(DOMAINS_DEPENDENCIES_PATH)
    domains = sorted(project.domains, key=domain_order_key)
    rows = [_table_row(DOMAINS_DEPENDENCIES_HEADER), "|" + "---|" * len(DOMAINS_DEPENDENCIES_HEADER)]
    diagram = ["```mermaid", "flowchart BT"]
    diagram += [f'  {DOMAIN_NODE_PREFIX}{d.name}["{_directory_name(d)}"]' for d in domains]
    for domain in domains:
        targets = [dep.target for dep in dependencies[domain.name]]
        source = ""
        if targets:
            source = links.link(
                f"`{_file_name('dependencies')}`", _file_id(domain, "dependencies"), file_path(domain, "dependencies"),
                _file_title(domain, "dependencies"),
            )
        rows.append(_table_row([
            _domain_link(links, domain, f"`{_directory_name(domain)}`"),
            "・".join(_domain_link(links, t, f"`{_directory_name(t)}`") for t in targets),
            source,
        ]))
        diagram += [f"  {DOMAIN_NODE_PREFIX}{domain.name} --> {DOMAIN_NODE_PREFIX}{t.name}" for t in targets]
    diagram.append("```")
    blocks = ["# ドメインの依存", "\n".join(rows), "\n".join(diagram)]
    return _document(f"{DOMAINS_DIR.as_posix()}/", None, blocks, links)


def render_domains_readme(project: Project, order: list[Domain]) -> str:
    """ドメインの読む順の索引。"""
    links = _Links(DOMAINS_README_PATH)
    dependencies_link = links.file_link(
        f"`{posixpath.basename(DOMAINS_DEPENDENCIES_PATH)}`", DOMAINS_DEPENDENCIES_PATH, "ドメインの依存"
    )
    rows = [_table_row(DOMAINS_README_HEADER), "|" + "---|" * len(DOMAINS_README_HEADER)]
    for number, domain in enumerate(order, start=1):
        rows.append(_table_row([
            str(number), _domain_link(links, domain, f"`{_directory_name(domain)}`"), escape_cell(domain.description),
        ]))
    blocks = [
        "# ドメインの読む順",
        f"ドメインの依存の表と図は {dependencies_link} にある。",
        "\n".join(rows),
    ]
    return _document(f"{DOMAINS_DIR.as_posix()}/", None, blocks, links)


def render_readme(domain: Domain, files: list[str]) -> str:
    """files は、表に載せるファイルの種類の記号。ドメインのディレクトリの直下にある手書きのファイル (concept・problem・design)
    を先に、このドメインで生成するファイル (models・unclassified_app_terms・functions・dependencies・terms) を後に並べる。"""
    path = f"{domain.dir}/{README}"
    links = _Links(path)
    blocks = [f"# {domain.full_name()}"]
    if domain.description:
        blocks.append(domain.description)
    if files:
        rows = ["| 文書 | 中身 |", "|---|---|"]
        for symbol in files:
            link = links.link(
                f"`{_file_name(symbol)}`", _file_id(domain, symbol), file_path(domain, symbol),
                _file_title(domain, symbol),
            )
            rows.append(f"| {link} | {FILE_DESCRIPTIONS[symbol]} |")
        blocks.append("\n".join(rows))
    return _document(f"{domain.dir}/", domain.id, blocks, links)


def render_gitattributes(paths: list[str], source: str = f"{DOMAINS_DIR.as_posix()}/") -> str:
    """paths は、ディレクトリ docs/ の下の生成するファイルの、リポジトリのルートからの相対パス (docs/.gitattributes を除く)。
    source は先頭の記述に書く生成元。"""
    base = posixpath.dirname(GITATTRIBUTES_PATH)
    lines = [generated_header.hash_line(source), GITATTRIBUTES_COMMENT]
    for path in sorted([*paths, GITATTRIBUTES_PATH]):
        if not path.startswith(f"{base}/"):
            raise ValueError(f"ディレクトリ {base}/ の外のファイルは {GITATTRIBUTES_PATH} に書けない: {path}")
        lines.append(f"/{posixpath.relpath(path, base)} merge=binary")
    return "\n".join(lines) + "\n"


def render_project(project: Project) -> dict[str, str]:
    """生成するファイルの、リポジトリのルートからの相対パスと内容。"""
    outputs: dict[str, str] = {}
    referencing = _referencing_models(project)
    dependencies = all_dependencies(project)
    for domain in project.domains:
        # 手書きのファイルは、今あるものを表に載せる (足したり消したりすると、検査 a が README.md の生成し直しを求める)
        files = [s for s in names.HANDWRITTEN_FILE_KINDS if (project.root / file_path(domain, s)).is_file()]
        if domain.models:
            outputs[file_path(domain, "models")] = render_models(project, domain, referencing)
            files.append("models")
        if domain.terms:
            outputs[file_path(domain, "unclassified_app_terms")] = render_unclassified_app_terms(domain)
            files.append("unclassified_app_terms")
        if domain.operations or domain.preconditions or domain.events:
            outputs[file_path(domain, "functions")] = render_functions(project, domain)
            files.append("functions")
        if dependencies[domain.name]:
            outputs[file_path(domain, "dependencies")] = render_dependencies(project, domain, dependencies[domain.name])
            files.append("dependencies")
        if any(True for _ in domain.entries()):
            outputs[file_path(domain, "terms")] = render_terms(domain)
            files.append("terms")
        outputs[f"{domain.dir}/{README}"] = render_readme(domain, files)
    if project.domains:
        outputs[DOMAINS_DEPENDENCIES_PATH] = render_domains_dependencies(project, dependencies)
        outputs[DOMAINS_README_PATH] = render_domains_readme(project, reading_order(project, dependencies))
    if project.roles or any(d.operations for d in project.domains):
        outputs[PERMISSIONS_PATH] = render_permissions(project)
    if project.roles or any(True for d in project.domains for _ in d.entries()):
        outputs[GLOSSARY_PATH] = render_glossary(project)
    if outputs:
        outputs[GITATTRIBUTES_PATH] = render_gitattributes(list(outputs), _project_source(project))
    return dict(sorted(outputs.items()))


def generated_files(root: Path) -> dict[str, generated_header.Header]:
    """ディレクトリ docs/ の下の、先頭の記述を持つファイル (生成したファイル) と、その記述。

    調べるのは、拡張子が .md と .yaml のファイルと、名前が .gitattributes のファイル。
    """
    found: dict[str, generated_header.Header] = {}
    docs = root / "docs"
    if not docs.is_dir():
        return found
    for path in sorted(docs.rglob("*")):
        if not path.is_file() or (path.suffix not in (".md", ".yaml") and path.name != ".gitattributes"):
            continue
        header = generated_header.read_file_header(path)
        if header is not None:
            found[path.relative_to(root).as_posix()] = header
    return found


HANDWRITTEN_MESSAGE = "手で書いたファイルが、生成するファイルの場所にある"


def is_handwritten(content: generated_header.FileContent) -> bool:
    """generated_header.read_file で読んだファイルが、手で書いたファイルか。

    先頭の記述が無く、空白と BOM (U+FEFF) 以外の文字があるファイルを、手で書いたファイルとする。
    空のファイルと、空白と BOM だけのファイル (生成したファイルが中身ごと消えたものなど) は、失う内容が無いので含めない。
    """
    return content.header is None and not content.is_blank


class HandwrittenFilesError(Exception):
    """生成するファイルの場所に手で書いたファイルがあるので、何も書かなかったことを表す。"""

    def __init__(self, paths: list[str]):
        super().__init__(f"{HANDWRITTEN_MESSAGE}: {', '.join(paths)}")
        self.paths = paths


def handwritten_fix(relative: str) -> str:
    """手で書いたファイルが生成するファイルの場所にあるときの直し方。"""
    if relative == GITATTRIBUTES_PATH:
        return (
            "手で書いた行を、パターンをリポジトリのルートからの相対に書き換えて (docs/.gitattributes のパターンは docs/ からの相対)、"
            "リポジトリのルートの .gitattributes に移してから、このファイルを消す"
        )
    return "ファイルの名前を変える。または、内容を手書きの文書に移してから、このファイルを消す"


def write_outputs(root: Path, outputs: dict[str, str]) -> tuple[list[str], list[str]]:
    """生成したファイルを書き、生成し直すと無くなるファイルを消す。書いたファイルと消したファイルを返す。

    消すのは、先頭の記述を持つファイル (生成したファイル) だけ。手書きのファイルは消さない。
    内容が同じファイルは書かない。生成するファイルの場所に手で書いたファイルがあれば、何も書かずに
    HandwrittenFilesError を送出する (呼び出し元が、そのパスの配列から利用者にエラーを伝える)。
    """
    # 生成するファイルの場所にある今のファイルを 1 回だけ読み、手で書いたファイルの判定と書く前の比較の両方に使う
    existing = {
        relative: generated_header.read_file(root / relative) for relative in outputs if (root / relative).is_file()
    }
    handwritten = [relative for relative, current in existing.items() if is_handwritten(current)]
    if handwritten:
        raise HandwrittenFilesError(handwritten)
    written: list[str] = []
    for relative, content in outputs.items():
        path = root / relative
        # 検査 a と同じ判定で比べる (改行の違いだけなら書かず、BOM や UTF-8 として読めないバイトがあれば上書きする)
        if relative in existing and existing[relative].matches(content):
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("w", encoding="utf-8", newline="\n") as f:
            f.write(content)
        written.append(relative)
    deleted: list[str] = []
    for relative

